func newMultiTrie(r *javadata.Reader) (rv *multiTrie, err error) {
    rv = &multiTrie{}
    rv.forward, err = r.ReadBool()
    if err != nil {
        return nil, err
    }
    rv.by, err = r.ReadInt32()
    if err != nil {
        return nil, err
    }
    nTries, err := r.ReadInt32()
    if err != nil {
        return nil, err
    }
    for nTries > 0 {
        trie, err := newTrie(r)
